import assert from 'node:assert/strict';
import { ToyRoomPhase } from '../src/js/toy-room/ToyRoomPhase.js';
const canvas={width:960,height:540,getContext:()=>({}),addEventListener(){},removeEventListener(){}};
const create=()=>new ToyRoomPhase(canvas,null,null,null,{bindInputs:false});
const phase=create();phase.startTutorial();
assert.equal(phase.gameplayState,'TOY_ROOM_TUTORIAL');
assert.match(phase.tutorial.message,/W A S D/);
phase.tutorial.setDevice('MOBILE_TOUCH');assert.match(phase.tutorial.message,/TOQUE E ARRASTE/);
phase.tutorial.setDevice('GAMEPAD');assert.match(phase.tutorial.message,/ANALÓGICO ESQUERDO/);
phase.tutorial.update(1);assert.equal(phase.tutorial.step,'movement');
phase.keysDown.KeyD=true;phase.update(1);phase.keysDown.KeyD=false;
assert.equal(phase.tutorial.step,'pickup');
assert.equal(phase.tutorial.target,phase.tutorial.nearest());
const guide=phase.tutorial.guidePosition();assert(guide.y<phase.tutorial.target.y-70);
const first=phase.tutorial.target;
phase.player.x=1140;phase.player.y=540;
for(let i=0;i<31;i++)phase.update(1);
assert.notEqual(phase.tutorial.target,first);assert.equal(phase.tutorial.target,phase.tutorial.nearest());
const target=phase.tutorial.target;
const prior={x:phase.fairy.x,y:phase.fairy.y};phase.update(1);
assert(Math.hypot(phase.fairy.x-prior.x,phase.fairy.y-prior.y)<100,'Troca de alvo sem teleporte');
for(let i=0;i<100;i++)phase.update(1);
phase.tutorial.setDevice('DESKTOP_KEYBOARD_MOUSE');assert.equal(phase.tutorial.message,'PRESSIONE E PARA PEGAR');
phase.tutorial.setDevice('MOBILE_TOUCH');assert.equal(phase.tutorial.message,'TOQUE NO BOTÃO PEGAR');
phase.tutorial.setDevice('GAMEPAD');assert.equal(phase.tutorial.message,'PRESSIONE X PARA PEGAR');
phase.player.x=target.x;phase.player.y=target.y;phase.lastActionTime=-Infinity;
phase.triggerAction();assert.equal(phase.player.carriedItem,target);
assert(phase.toyRoomTutorialCompleted);assert.equal(phase.tutorial.active,false);assert.equal(phase.tutorial.target,null);
const restored=create();restored.restore(phase.snapshot());restored.startTutorial();assert.equal(restored.tutorial.active,false);
const fresh=create();fresh.startTutorial();assert.equal(fresh.tutorial.active,true);
// Sem conclusão gravada, inclusive em saves antigos, a orientação pode ser retomada.
const old=phase.snapshot();delete old.toyRoomTutorialCompleted;old.carriedItemId=null;
const legacy=create();legacy.restore(old);assert.equal(legacy.tutorial.active,true);
const chest=phase.furniture.find(f=>f.id==='toy-chest');
phase.player.x=chest.x+chest.w/2;phase.player.y=chest.y+chest.h/2;phase.lastActionTime=-Infinity;
phase.triggerAction();assert.equal(phase.organizedCount,1);assert.equal(phase.tutorial.active,false);
console.log('APROVADO: movimento real, três instruções, alvo coletável, troca suave, primeira coleta, armazenamento e persistência.');
const descriptor=Object.getOwnPropertyDescriptor(globalThis,'navigator');
const pad={index:0,connected:true,mapping:'standard',axes:[0,0],buttons:[{},{},{pressed:false,value:0}]};
let pads=[pad];Object.defineProperty(globalThis,'navigator',{configurable:true,value:{getGamepads:()=>pads}});
const controlled=create();controlled.startTutorial();controlled.update(1);
assert.equal(controlled.tutorial.device,'GAMEPAD');assert.match(controlled.tutorial.message,/ANALÓGICO/);
pad.axes=[0.8,0];const x=controlled.player.x;controlled.update(1);assert(controlled.player.x>x);
pad.axes=[0,0];controlled.handleKeyDown({code:'KeyW'});controlled.update(1);controlled.handleKeyUp({code:'KeyW'});
assert.equal(controlled.tutorial.device,'DESKTOP_KEYBOARD_MOUSE');
const t=controlled.tutorial.target;controlled.player.x=t.x;controlled.player.y=t.y;
controlled.lastActionTime=-Infinity;pad.buttons[2]={pressed:true,value:1};controlled.update(1);
assert.equal(controlled.player.carriedItem,t);assert(controlled.toyRoomTutorialCompleted);
controlled.lastActionTime=-Infinity;controlled.update(1);assert.equal(controlled.player.carriedItem,t,'X segurado não repete a ação');
pads=[];controlled.update(1);assert.equal(controlled.gamepadState.active,false);
assert.equal(controlled.tutorial.device,'DESKTOP_KEYBOARD_MOUSE');
if(descriptor)Object.defineProperty(globalThis,'navigator',descriptor);else delete globalThis.navigator;
console.log('APROVADO: analógico, X por pressionamento, troca teclado/gamepad e desconexão.');
